@file:Suppress(
    "RETURN_VALUE_NOT_USED",
    "RETURN_VALUE_NOT_USED_COERCION",
)

import com.varabyte.kobweb.core.AppGlobals
import com.varabyte.kobweb.core.`init`.InitKobwebContext
import com.varabyte.kobweb.navigation.BasePath
import com.varabyte.kobweb.navigation.Router
import com.varabyte.kobweb.navigation.UpdateHistoryMode
import com.varabyte.kobweb.navigation.remove
import com.varabyte.kobweb.silk.defer.DeferringHost
import kotlin.Suppress
import kotlinx.browser.document
import kotlinx.browser.window
import org.jetbrains.compose.web.renderComposable
import com.parodison.orbital.system.components.layouts.ResponsiveLayout as _com_parodison_orbital_system_components_layouts_ResponsiveLayout
import com.parodison.orbital.system.pages.HomePage as _com_parodison_orbital_system_pages_HomePage
import com.parodison.orbital.system.pages.mapa.MapScreen as _com_parodison_orbital_system_pages_mapa_MapScreen

public fun main() {
    AppGlobals.initialize(mapOf("title" to "App"))
    BasePath.set("")
    val router = Router()
    com.varabyte.kobweb.core.init.initKobweb(router) { ctx ->
        ctx.router.registerLayout(
            "com.parodison.orbital.system.components.layouts.ResponsiveLayout",
        ) { pageCtx, pageMethod -> 
            _com_parodison_orbital_system_components_layouts_ResponsiveLayout(pageCtx) {
                pageMethod(pageCtx)
            }
        }
        ctx.router.register(
            "/",
            layoutId = "com.parodison.orbital.system.components.layouts.ResponsiveLayout",
        ) { pageCtx -> 
            _com_parodison_orbital_system_pages_HomePage()
        }
        ctx.router.register(
            "/mapa/",
            layoutId = "com.parodison.orbital.system.components.layouts.ResponsiveLayout",
        ) { pageCtx -> 
            _com_parodison_orbital_system_pages_mapa_MapScreen()
        }

        com.parodison.orbital.system.di.initKoin(ctx)
    }
    router.addRouteInterceptor {
        path = path.removeSuffix(".html").removeSuffix(".htm")
    }

    com.varabyte.kobweb.silk.init.additionalSilkInitialization = { ctx ->
        com.varabyte.kobweb.silk.init.initSilkWidgets(ctx)
        com.varabyte.kobweb.silk.init.initSilkWidgetsKobweb(ctx)
        ctx.theme.registerStyle("icon-hover", com.parodison.orbital.system.components.satellite.IconHoverStyle)
        ctx.theme.registerStyle("satellite-card-container", com.parodison.orbital.system.components.satellite.SatelliteCardContainerStyle)
        ctx.theme.registerStyle("md-slider", com.parodison.orbital.system.components.tracking.MdSliderStyle)
        ctx.theme.registerStyle("basic-input", com.parodison.orbital.system.components.dom.BasicInputStyle)
        ctx.theme.registerStyle("animated-visibility", com.parodison.orbital.system.components.dom.AnimatedVisibilityStyle)
        ctx.theme.registerStyle("button", com.parodison.orbital.system.components.dom.ButtonStyle)
        ctx.theme.registerStyle("side-bar-element", com.parodison.orbital.system.components.sidebar.SideBarElementStyle)
        ctx.theme.registerStyle("sidebar-span", com.parodison.orbital.system.components.sidebar.SidebarSpanStyle)
        com.parodison.orbital.system.initTheme(ctx)
    }

    // Dedup any leading slashes after removing the origin, just in case someone typed
    // something like `https://site.com//about` by accident. If we pass `//about` into
    // `tryRoutingTo`, Kobweb will reject it as a protocol-relative URL; instead, we
    // want it to navigate to `/about`
    router.tryRoutingTo(BasePath.remove("/" + window.location.href.removePrefix(window.origin).trimStart('/')), UpdateHistoryMode.REPLACE)

    // For SEO, we may bake the contents of a page in at build time. However, we will
    // overwrite them the first time we render this page with their composable, dynamic
    // versions. Think of this as poor man's hydration :)
    // See also: https://en.wikipedia.org/wiki/Hydration_(web_development)
    val root = document.getElementById("_kobweb-root")!!
    while (root.firstChild != null) { root.removeChild(root.firstChild!!) }

    renderComposable(rootElementId = "_kobweb-root") {
        com.parodison.orbital.system.AppEntry {
            router.renderActivePage { DeferringHost { it() } }
        }
    }
}
